   foreach(var mission in Simulation.Missions){var m=mission;missionLabels[m]=Label(q,"Mission_"+m.id,"",0,j*30,223,28,13,Gold);var qb=Button(q,"QTE_"+m.id,m.qte?"已接管":"接管",224,j++*30,74,27,()=>OpenQTE(m),13);qb.interactable=!m.qte&&!Simulation.Over;}
