  void UpdateUnknownText(){currentViewing.text=DemoSystemDiscovery.UnknownView;details.text=DemoSystemDiscovery.UnknownDetails;foreach(var p in jobLabels)p.Value.text=(p.Key.kind=="apply"?"资源申请":rules.Find(p.Key.kind,p.Key.key).name)+"  "+Math.Ceiling(p.Key.left)+"s";foreach(var p in missionLabels)p.Value.text=Simulation.MissionName(p.Key)+" "+Math.Ceiling(p.Key.left)+"s";}
  void UpdateSideText(){if(status==null)return;var b=Simulation.Body;details.text=Simulation.SelectedShip>=0?(Simulation.Ship==null||Simulation.Ship.done?"所选外逃舰已离场或被阻截":"所选外逃舰离场剩余 "+Math.Ceiling(Simulation.Ship.left)+" 游戏秒\n命中后人口返回出发天体\n请使用外逃阻截作业"):ReconDetails();currentViewing.text=CurrentViewingText();
   if(!DemoSystemDiscovery.Revealed(Simulation)){UpdateUnknownText();return;}
   for(int i=0;i<b.nodes.Count;i++){var n=b.nodes[i];Text t;if(nodeLabels.TryGetValue(n.id,out t)){t.GetComponentInParent<Button>().interactable=n.hp>0;t.text=n.type+"中心 "+(i+1)+"  "+n.hp.ToString("0")+" / "+n.max+" HP"+(Simulation.TargetNode==n.id?" ◀":"");}}
   var known=Simulation.Bodies.Where(x=>x.recon&&x.kind!="star").ToArray();status.text="察觉 "+Simulation.Alert.ToString("0.0")+" / 已侦察 "+known.Length+" 个天体\n已揭示人口 "+known.Sum(x=>x.pop).ToString("0.0")+"P\n已揭示中心损毁 "+known.Sum(x=>x.nodes.Count(n=>n.hp<=0))+" / "+known.Sum(x=>x.nodes.Count)+"\n打击顺序：自由选择"+"\n外逃 "+Simulation.Escaped+" · "+(Simulation.Escaped>0?"成功逃出已记录":"本关无成功外逃")+"\n已揭示备份 "+(known.Length==0?"待侦察":known.Sum(x=>x.backup).ToString("0.0"))+"\n主要威胁："+(!b.recon?"待侦察":b.nodes.Any(n=>n.type=="军事"&&n.hp>0)?"军事中心仍在运作":"未发现存活军事中心");
   foreach(var p in jobLabels)p.Value.text=(p.Key.kind=="apply"?"资源申请":rules.Find(p.Key.kind,p.Key.key).name)+"  "+Math.Ceiling(p.Key.left)+"s";foreach(var p in missionLabels)p.Value.text=Simulation.MissionName(p.Key)+" "+Math.Ceiling(p.Key.left)+"s";
  }
  public void Refresh(){if(Simulation==null)return;var objective=ui.Find("Objective");if(objective!=null)objective.GetComponent<Text>().text="人口清零 + 限时完成 · "+(Simulation.AllowsEscape?"外逃记入评分与结局":Simulation.ReportedNoEscape?"已上报：禁止任何外逃":"禁止任何外逃");RefreshProgressionButtons();RefreshSolarDialogue();if(applyButton!=null)applyButton.interactable=Simulation.CanApply&&!Simulation.Over;tutorialText.text=Simulation.TutorialHint;title.text=Simulation.Level.title;clock.text=DemoSimulation.Clock(Simulation.Level.limit-Simulation.Time);pause.GetComponentInChildren<Text>().text=Simulation.Paused?"继续":"暂停";if(lastRevision!=Simulation.Revision||sideBody!=Simulation.Selected)RefreshSide();else UpdateSideText();RefreshButtons();RefreshManifest();inventoryHud.Refresh(Simulation);}
  void Update(){if(Simulation==null)return;if(TickNarrative()){RecordNarrativeFacts();return;}PollFunctionShortcuts();if(Input.GetKeyDown(KeyCode.Escape))HandleEscape();if(Input.GetKeyDown(KeyCode.Space)&&!modal.gameObject.activeSelf&&!TextEntryFocused()&&!DropdownOpen()&&!Simulation.Over){Simulation.Paused=!Simulation.Paused;Refresh();}Simulation.Advance(Time.deltaTime*Simulation.Speed);RecordNarrativeFacts();PositionLabels();map.Refresh();if(preview!=null)preview.Refresh();uiTimer+=Time.unscaledDeltaTime;if(uiTimer>=.25f){uiTimer=0;Refresh();}if(qteMission!=null&&modal.gameObject.activeSelf){float t=((Time.unscaledTime-qteStart)%1.5f)/1.5f;qteDot.anchoredPosition=new Vector2(35+t*815,-285);}if(Simulation.Over&&!resultShown){resultShown=true;OpenResults();}}
void PositionLabels(){if(baseName!=null)baseName.rectTransform.anchoredPosition=map.LaunchBasePosition+new Vector2(-76,-14);var occupied=new List<Rect>();map.LabelPositions.Clear();foreach(var b in Simulation.Bodies){bool visible=DemoSystemDiscovery.Revealed(Simulation)&&map.Positions.ContainsKey(b.id);bodyLabels[b.id].gameObject.SetActive(visible);Image artImage;if(bodyImages.TryGetValue(b.id,out artImage))artImage.gameObject.SetActive(visible);if(!visible)continue;var p=map.LocalPosition(b.id);float width=Mathf.Max(35,b.name.Length*(b.kind=="planet"||b.kind=="star"?14:11));Vector2 label=p+new Vector2(13,16);if(label.x+width>1240)label.x=p.x-width-13;
    for(int attempt=0;attempt<16;attempt++){float shift=attempt==0?0:((attempt+1)/2)*19*(attempt%2==0?-1:1);Vector2 test=label+new Vector2(0,shift);test.y=Mathf.Clamp(test.y,-map.rectTransform.rect.height+76,-34);var bounds=new Rect(test.x,-test.y,width,18);if(!occupied.Any(r=>r.Overlaps(bounds))||attempt==15){label=test;occupied.Add(bounds);break;}}
    bodyLabels[b.id].rectTransform.anchoredPosition=label;map.LabelPositions[b.id]=label;Image img;if(bodyImages.TryGetValue(b.id,out img))img.rectTransform.anchoredPosition=p+new Vector2(-img.rectTransform.sizeDelta.x/2,img.rectTransform.sizeDelta.y/2);
   }
   foreach(var b in Simulation.Bodies)for(int i=0;i<b.nodes.Count;i++){var n=b.nodes[i];Text label;if(!mapNodeLabels.TryGetValue(n.id,out label))continue;Vector2 p;bool visible=b.recon&&map.NodePositions.TryGetValue(n.id,out p);label.gameObject.SetActive(visible);if(visible){p=map.NodePositions[n.id];label.rectTransform.anchoredPosition=p+new Vector2(-38,-12);label.text=n.type+" "+(i+1)+"\n"+n.hp.ToString("0")+" HP";label.color=n.hp>0?PrototypeUi.Ink:Muted;}}
  }
  bool IsVisibleLog(string line){if(string.IsNullOrEmpty(line))return true;if(!DemoSystemDiscovery.Revealed(Simulation)&&Simulation.Bodies.Any(b=>line.Contains(b.name)))return false;if(line.Contains("待命 ·")&&line.Contains("P。"))return false;if((line.Contains("AI开始")||line.Contains("AI完成")||line.Contains("挂靠中心"))&&Simulation.Bodies.Any(b=>!b.recon))return false;return !Simulation.Bodies.Any(b=>!b.recon&&line.Contains(b.name)&&(line.Contains("中心已摧毁")||line.Contains("备份")||line.Contains("病菌")));}
  void OpenModal(){if(!modal.gameObject.activeSelf)beforeModal=Simulation.Paused;Simulation.Paused=true;Clear(dialog);modal.gameObject.SetActive(true);}void CloseModal(){modal.gameObject.SetActive(false);qteMission=null;Simulation.Paused=beforeModal;Refresh();}
  public void ShowInventoryItem(string kind,string key){
   var rule=rules.Find(kind=="armament"?"batch":kind,key);OpenModal();Label(dialog,"InventoryTitle",rule.name+" · 物资储备",35,24,850,50,29,Gold);
   int pending=Simulation.Jobs.Count(j=>j.kind==(kind=="armament"?"batch":kind)&&j.key==key);
   string stock=kind=="carrier"?Simulation.Carriers[key].ToString():kind=="research"?(Simulation.Research.ContainsKey(key)?"1 / 1（已研发）":"0 / 1（未研发）"):kind=="armament"?Math.Floor(Simulation.Res[3+int.Parse(key.Substring(1))-1]).ToString():kind=="technologyModule"?Simulation.TechnologyModules[key].ToString():Simulation.AttackModules[key].ToString();
   string detail="可用储备 "+stock+"\n"+(kind=="research"?"在研 ":"在造 ")+pending+"\n解锁关卡：第"+rule.unlock+"关\n\n"+(kind=="research"?"科技为本关持续生效的研发成果，不在发射时消耗。":(kind=="attackModule"||kind=="technologyModule")?"制造时扣费 → 完成后入库 → 搭载 → 发射扣1个库存，不重复扣制造费。":kind=="carrier"?"制造完成后入库 → 发射扣除1个。制造中的载体不计入可用库存。":"制造完成后加入独立库存，预装配或即时发射会消耗对应武装。")+"\n\n"+(rule.Description??"");
   Label(dialog,"InventoryDescription",detail,35,100,850,370,21);Button(dialog,"CloseInventory","返回战场",35,535,250,55,CloseModal);
   Button(dialog,"GoInventoryProduction",kind=="research"?"前往研发":(kind=="attackModule"||kind=="technologyModule")?"前往模块制造":"前往制造",310,535,250,55,()=>{CloseModal();if(kind=="technologyModule"){moduleGroup="technologyModule";SetTab("attackModule");}else SetTab(kind=="armament"?"batch":kind);});
  }
  void OpenHelp(){OpenModal();Label(dialog,"HelpTitle","作业操作说明",35,24,850,50,29,Gold);Label(dialog,"HelpText",BriefingText()+"\n\n建造经济 → 军工/信号 → 制造打击／科技模块 → 制造载体 → 星系探测 → 深度侦察 → 选择城市或中心 → 选载体 → 搭载模块 → 发射。\n\n单击仍可直接下令；进入局部后点击中心图标与右侧列表选中同一目标。外逃舰可点图标或目录选中，使用外逃阻截。\n\nQ/W/E/R/T/Y/U：生产/资源/载体/研发/模块制造/投送/申请；同键收起，Esc先关闭菜单，再打开暂停。\n\n左下资源储备与右侧列表支持滚轮；城市承接人口伤害，中心承接耐久伤害。恒星打击同时伤害全域中心与人口。无需清除固定比例中心即可消灭人口。\n\n继续或空格启停，1× / 2× / 4×切换速度。暂停期间可以安排作业，所有计时停止。投送校准可选，自动结算无需接管。\n\n前3关人口清零、限时内完成、零外逃；第4关外逃不阻断通关。信息残留、最低知情、熵增控制进入评分。",35,92,850,420,21);Button(dialog,"CloseHelp","返回战场",35,545,250,55,CloseModal);}
  void OpenQTE(DemoMission m){if(m.qte||Simulation.Over)return;OpenModal();qteMission=m;qteStart=Time.unscaledTime;Label(dialog,"QTETitle","载荷校准 · 可选接管",35,24,850,50,29,Gold);Label(dialog,"QTENote","光点进入中央绿色窗口后锁定。\n成功：效果×"+rules.mechanics.calibrationSuccess+"，缩短"+rules.mechanics.calibrationTimeSaved+"秒；失误：效果×"+rules.mechanics.calibrationFailure+"，察觉+"+rules.mechanics.calibrationFailureAlert+"。\n校准期间战场暂停，取消则恢复自动执行。",35,100,850,145,21);PrototypeUi.Box(dialog,"Track",35,280,835,26,new Color32(37,51,71,255));PrototypeUi.Box(dialog,"Window",369,280,167,26,new Color32(72,131,94,255));qteDot=PrototypeUi.Box(dialog,"Dot",35,285,12,16,PrototypeUi.Accent).rectTransform;Button(dialog,"LockQTE","锁定",35,375,260,55,()=>{float t=((Time.unscaledTime-qteStart)%1.5f)/1.5f;Simulation.Calibrate(m,t>=.4f&&t<=.6f);CloseModal();});Button(dialog,"CancelQTE","取消接管",315,375,260,55,CloseModal);}
  void OpenResults(){string progressError=null;bool saved=false;if(Simulation.Won){try{saved=DemoSession.RecordVictory(Simulation);}catch(Exception ex){progressError=ex.Message;}}OpenModal();Label(dialog,"ResultTitle",Simulation.Won?"清理完成":"任务失败",35,24,850,50,32,Simulation.Won?PrototypeUi.Accent:Gold);Label(dialog,"Results",Simulation.ResultReason+"\n\n已用 "+DemoSimulation.Clock(Simulation.Time)+" / "+DemoSimulation.Clock(Simulation.Level.limit)+"\n天体与在途剩余人口 "+Simulation.Remaining.ToString("0.0")+"P · 中心清除 "+Simulation.Cleared+" / "+Simulation.InitialNodes+"\n外逃 "+Simulation.Escaped+"次 / "+Simulation.EscapedPop.ToString("0.0")+"P · "+(Simulation.Escaped>0?"外逃事实已记录；结局尚需综合剧情判定":"本关无成功外逃")+"\n\n信息清理 "+Simulation.InformationScore.ToString("0")+" · 最低知情 "+Simulation.KnowledgeScore.ToString("0")+" · 熵增控制 "+Simulation.EntropyScore.ToString("0")+"\n\n"+(Simulation.AllowsEscape?"外逃和备份残留不阻断本关；已外逃人口独立记录。":"本关禁止外逃；备份残留进入评分。"),35,95,850,360,22);Label(dialog,"ProgressResult",progressError!=null?"通关进度保存失败："+progressError:!Simulation.Won?"未解锁下一关；重试完成当前关卡目标。":Simulation.Level.number<DemoProgression.LevelCount?"已解锁第"+(Simulation.Level.number+1)+"关，进度已保存。":"全部关卡已完成，可返回办公室重玩。",35,463,850,45,17,progressError!=null?Gold:PrototypeUi.Accent);Button(dialog,"Retry","重试本关",35,520,240,55,()=>LoadLevel(Simulation.Level.number));Button(dialog,"Inspect","查看战场",295,520,240,55,CloseModal);if(saved)Button(dialog,"NextLevel","返回办公室 / 剧情",555,520,300,55,()=>UnityEngine.SceneManagement.SceneManager.LoadScene("Office"));else if(progressError!=null)Button(dialog,"RetryProgressSave","重试保存进度",555,520,300,55,OpenResults);RefreshProgressionButtons();}
  InputField NumberInput(string name,double value,float y){var box=PrototypeUi.Box(dialog,name,570,y,280,35,new Color32(28,41,59,255));box.raycastTarget=true;var f=box.gameObject.AddComponent<InputField>();f.targetGraphic=box;f.textComponent=Label(box.transform,"Text","",12,0,256,35,18);f.contentType=InputField.ContentType.DecimalNumber;f.text=value.ToString(System.Globalization.CultureInfo.InvariantCulture);return f;}
  void OpenSettings(){OpenModal();Label(dialog,"SettingsTitle",Simulation.Level.title+" · 基准调参",35,18,850,50,29,Gold);string[] names={"时限（秒）","初始人口P","硅基恢复倍率","能源基础 / 秒","物质基础 / 秒","玩家伤害倍率","AI成长倍率","科技基础 / 秒","外逃准备秒","AI建造点 / 秒"};var l=Simulation.Level;double[] values={l.limit,l.population,l.regenerationScale,l.energyRate,l.matterRate,l.damageScale,l.aiScale,l.techRate,l.escapeSeconds,l.aiBuildRate};var inputs=new List<InputField>();for(int i=0;i<names.Length;i++){Label(dialog,"SettingLabel"+i,names[i],35,83+i*40,500,35,18);inputs.Add(NumberInput("Setting"+i,values[i],83+i*40));}var error=Label(dialog,"SettingError","应用后重开本关；永久调整可编辑 DemoCampaign 配置资产。",35,490,850,43,15,Muted);
   Button(dialog,"ApplySettings","应用并重开",35,545,260,55,()=>{var v=new double[inputs.Count];for(int i=0;i<v.Length;i++)if(!double.TryParse(inputs[i].text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out v[i])||double.IsNaN(v[i])||double.IsInfinity(v[i])){error.text="参数必须是有效数字";return;}var copy=l.Copy();copy.limit=v[0];copy.population=v[1];if(copy.bodies!=null&&l.population>0)foreach(var b in copy.bodies)b.population*=copy.population/l.population;copy.regenerationScale=v[2];copy.energyRate=v[3];copy.matterRate=v[4];copy.damageScale=v[5];copy.aiScale=v[6];copy.techRate=v[7];copy.escapeSeconds=v[8];copy.aiBuildRate=v[9];try{copy.Validate();}catch(Exception ex){error.text=ex.Message;return;}var original=Campaign;var temp=ScriptableObject.CreateInstance<DemoCampaign>();temp.levels=new[]{copy};Campaign=temp;LoadLevel(copy.number);Campaign=original;Destroy(temp);});Button(dialog,"CancelSettings","返回战场",315,545,260,55,CloseModal);
  }
